"use client";

import { loadFont } from "@remotion/google-fonts/BarlowCondensed";
import type React from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
  spring,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  easeCount,
  type WeightCutElementId,
  weightCutTimeline,
} from "./timeline";

const WEIGHTS = ["100", "200", "300", "400", "500"] as const;
const barlow = loadFont("normal", {
  weights: [...WEIGHTS],
  subsets: ["latin"],
});

export interface WeightCutProps {
  value?: number;
  from?: number;
  decimals?: number;
  prefix?: string;
  suffix?: string;
  eyebrow?: string;
  label?: string;
  lightWeight?: number;
  accent?: string;
  /** Text color of the figure and label; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the copy. Load it yourself; Barlow Condensed by default. */
  fontFamily?: string;
  /** Frames the figure takes to count from `from` to `value`. */
  count?: number;
  /** Size of the figure and copy, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the entry, the eyebrow, the count, single
   * digit drops and the label, by the ids in `./timeline`. Frames on the
   * scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<WeightCutElementId>;
}

const THEMES = {
  dark: {
    bg: "#000000",
    ink: "#FFFFFF",
    accent: "#D4FF00",
  },
  light: {
    bg: "#D4FF00",
    ink: "#000000",
    accent: "#000000",
  },
} as const;

const TRACK = 0.01;
const SUFFIX_SCALE = 0.3;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  adv: Record<string, number>;
  slot: number;
  stemLight: number;
  stemHeavy: number;
  baseline: number;
  figTop: number;
}

function snapWeight(w: number) {
  const v = Math.min(500, Math.max(100, w));
  return Math.round(v / 100) * 100;
}

function measure(chars: string[], light: number, fontFamily: string): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  const adv: Record<string, number> = {};
  let slot = 0.45;
  let stemLight = 0.02;
  let stemHeavy = 0.1;
  let baseline = 0.8;
  let figTop = 0.7;
  if (!ctx) {
    for (const ch of chars) adv[ch] = 0.45;
    return { adv, slot, stemLight, stemHeavy, baseline, figTop };
  }
  const ink = (w: number) => {
    ctx.font = `${w} 200px "${fontFamily}"`;
    const mm = ctx.measureText("I");
    return (mm.actualBoundingBoxLeft + mm.actualBoundingBoxRight) / 200;
  };
  stemHeavy = ink(500);
  stemLight = ink(light);
  ctx.font = `${light} 200px "${fontFamily}"`;
  for (const ch of chars) adv[ch] = ctx.measureText(ch).width / 200;
  slot = Math.max(
    ...Array.from({ length: 10 }, (_, d) => adv[String(d)] ?? 0.4),
  );
  const fm = ctx.measureText("0");
  const asc = fm.fontBoundingBoxAscent / 200;
  const desc = fm.fontBoundingBoxDescent / 200;
  baseline = (1 - (asc + desc)) / 2 + asc;
  figTop = fm.actualBoundingBoxAscent / 200;
  return { adv, slot, stemLight, stemHeavy, baseline, figTop };
}

function useMetrics(chars: string[], light: number, fontFamily: string) {
  const key = `${light}\u0002${chars.join("\u0001")}\u0002${fontFamily}`;
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("weight-cut: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const [lw, list] = key.split("\u0002");
    Promise.all([
      barlow.waitUntilDone(),
      ...WEIGHTS.map((w) => document.fonts.load(`${w} 100px "${fontFamily}"`)),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({
          key,
          m: measure(list.split("\u0001"), Number(lw), fontFamily),
        });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, handle, fontFamily]);
  return state && state.key === key ? state.m : null;
}

function format(v: number, decimals: number) {
  return v.toLocaleString("en-US", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function WeightCut(props: WeightCutProps) {
  const {
    value = 6.8,
    from = 94,
    decimals = 1,
    prefix = "",
    suffix = "KB",
    eyebrow = "Per scene, gzipped",
    label = "Lighter than your logo file.",
    lightWeight = 100,
    accent,
    ink,
    background,
    fontFamily = barlow.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    weightCutTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const enterEl = tl.get("enter");
  const eyebrowEl = tl.get("eyebrow");
  const countEl = tl.get("count");
  const labelEl = tl.get("label");
  const countEnd = countEl.end;
  const c = THEMES[theme];
  const spot = accent ?? c.accent;
  const fg = ink ?? c.ink;
  const light = snapWeight(lightWeight);
  const chars = useMemo(
    () =>
      Array.from(
        new Set(["0123456789.,", prefix, suffix.toUpperCase()].join("")),
      ),
    [prefix, suffix],
  );
  const m = useMetrics(chars, light, fontFamily);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  const drops = tl.lane("Digits").map((e) => ({ at: e.start }));

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const s = portrait ? W / 1080 : Math.min(W / 1280, H / 720);

  const g = interpolate(t, [countEl.start, countEnd], [0, 1], {
    ...CLAMP,
    easing: easeCount,
  });
  const raw = from + (value - from) * g;
  const shown = Math.round(raw * 10 ** decimals) / 10 ** decimals;
  const text = `${prefix}${format(shown, decimals)}`;
  const span = from - value;
  const heavy = span === 0 ? 0 : Math.min(1, Math.max(0, (raw - value) / span));

  const enter = interpolate(t, [enterEl.start, enterEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const relax = spring({
    frame: t - (countEnd - countEl.beat("relax")),
    fps,
    config: { damping: 18, stiffness: 120, mass: 0.9 },
  });
  const closing = drops
    .filter((d) => t >= d.at)
    .map((d) =>
      spring({
        frame: t - d.at,
        fps,
        config: { damping: 16, stiffness: 140, mass: 0.8 },
      }),
    )
    .filter((k) => k < 0.999);

  const sufText = suffix.toUpperCase();
  const advOf = (ch: string) => m.adv[ch] ?? m.slot;
  const startText = `${prefix}${format(from, decimals)}`;
  const startEm =
    Array.from(startText).reduce(
      (a, ch) => a + (/[0-9]/.test(ch) ? m.slot : advOf(ch)) + TRACK,
      0,
    ) +
    m.stemHeavy +
    (sufText
      ? 0.03 +
        Array.from(sufText).reduce((a, ch) => a + advOf(ch), 0) * SUFFIX_SCALE +
        m.stemHeavy * SUFFIX_SCALE
      : 0);

  const margin = portrait ? W * 0.07 : W * 0.05;
  const colW = portrait ? 0 : W * 0.28;
  const roomW = W - margin * 2 - colW;
  const F = Math.min(
    roomW / Math.max(0.2, startEm),
    (H * (portrait ? 0.3 : 0.76)) / m.figTop,
  );
  const stroke = Math.max(0, m.stemHeavy - m.stemLight) * F * heavy;
  const baseY = portrait ? H * 0.62 : H - margin;
  const boxTop = baseY - m.baseline * F;

  const glyphs: { ch: string; x: number; w: number }[] = [];
  let x = margin + stroke / 2;
  for (const k of closing) x += m.slot * F * (1 - k);
  for (const ch of Array.from(text)) {
    const natural = advOf(ch);
    const w =
      (/[0-9]/.test(ch) ? m.slot + (natural - m.slot) * relax : natural) * F +
      TRACK * F +
      stroke;
    glyphs.push({ ch, x, w });
    x += w;
  }
  const numRight = x;
  const sufF = F * SUFFIX_SCALE;

  const eyebrowFs = (portrait ? 40 : 26) * s;
  const labelFs = (portrait ? 72 : 52) * s;
  const eyebrowP = interpolate(t, [eyebrowEl.start, eyebrowEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const labelP = interpolate(t, [labelEl.start, labelEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });

  const figure = {
    position: "absolute" as const,
    whiteSpace: "pre" as const,
    fontFamily,
    fontWeight: light,
    color: fg,
    WebkitTextStroke:
      stroke > 0.05 ? `${stroke.toFixed(2)}px ${fg}` : undefined,
  };

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            opacity: enter,
            transform: `translateY(${((1 - enter) * F * 0.06).toFixed(2)}px)${glide(midway(enter))}`,
          }}
        >
          {glyphs.map((gl, i) => (
            <div
              key={i}
              style={{
                ...figure,
                left: gl.x,
                width: gl.w,
                top: boxTop,
                height: F,
                lineHeight: `${F}px`,
                textAlign: "center",
                fontSize: F,
              }}
            >
              {gl.ch}
            </div>
          ))}
          {sufText ? (
            <div
              style={{
                ...figure,
                left: numRight + F * 0.03,
                top: baseY - m.baseline * sufF,
                height: sufF,
                lineHeight: `${sufF}px`,
                fontSize: sufF,
                WebkitTextStroke:
                  stroke > 0.05
                    ? `${(stroke * SUFFIX_SCALE).toFixed(2)}px ${fg}`
                    : undefined,
              }}
            >
              {sufText}
            </div>
          ) : null}
        </div>

        <div
          style={{
            position: "absolute",
            ...(portrait
              ? { left: margin, right: margin, top: margin * 1.6 }
              : { right: margin, width: colW - margin * 0.5, top: margin }),
            display: "flex",
            flexDirection: "column",
            alignItems: "flex-start",
            gap: eyebrowFs * 0.7,
            fontFamily,
            textTransform: "uppercase",
          }}
        >
          {eyebrow ? (
            <div
              style={{
                fontWeight: 500,
                fontSize: eyebrowFs,
                lineHeight: 1,
                color: spot,
                opacity: eyebrowP,
              }}
            >
              {eyebrow}
            </div>
          ) : null}
          {label ? (
            <div
              style={{
                fontWeight: 500,
                fontSize: labelFs,
                lineHeight: 0.94,
                color: fg,
                textWrap: "balance",
                opacity: labelP,
                transform: `translateY(${((1 - labelP) * labelFs * 0.4).toFixed(2)}px)${glide(midway(labelP))}`,
              }}
            >
              {label}
            </div>
          ) : null}
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The figure fading up, the eyebrow, the count down from `from` (each digit
// the figure loses closing its slot) and the label. Frames on the 30 fps
// scene timeline, after `delay` and `speed`. The ids are public: a saved
// `timing` prop refers to them.

export type WeightCutElementId =
  | "enter"
  | "eyebrow"
  | "count"
  | `drop:${number}`
  | "label";

export interface WeightCutTimingProps {
  value?: number;
  from?: number;
  decimals?: number;
  count?: number;
}

const ENTER_AT = -5;
const ENTER_END = 14;
const COUNT_AT = 20;
const COUNT_END = 78;
const LABEL_AT = 64;

// The count's easing, `Easing.bezier(0.3, 0, 0.12, 1)` from Remotion,
// written out so the schedule can find the frames the figure loses a digit
// without importing Remotion. Same algorithm, same numbers.
const kSplineTableSize = 11;
const kSampleStepSize = 1.0 / (kSplineTableSize - 1.0);
const coefA = (a1: number, a2: number) => 1.0 - 3.0 * a2 + 3.0 * a1;
const coefB = (a1: number, a2: number) => 3.0 * a2 - 6.0 * a1;
const coefC = (a1: number) => 3.0 * a1;
const calcBezier = (t: number, a1: number, a2: number) =>
  ((coefA(a1, a2) * t + coefB(a1, a2)) * t + coefC(a1)) * t;
const getSlope = (t: number, a1: number, a2: number) =>
  3.0 * coefA(a1, a2) * t * t + 2.0 * coefB(a1, a2) * t + coefC(a1);

function cubicBezier(mX1: number, mY1: number, mX2: number, mY2: number) {
  const samples = new Float32Array(kSplineTableSize);
  for (let i = 0; i < kSplineTableSize; ++i) {
    samples[i] = calcBezier(i * kSampleStepSize, mX1, mX2);
  }
  const tForX = (aX: number) => {
    let intervalStart = 0.0;
    let current = 1;
    const last = kSplineTableSize - 1;
    for (; current !== last && samples[current] <= aX; ++current) {
      intervalStart += kSampleStepSize;
    }
    --current;
    const dist =
      (aX - samples[current]) / (samples[current + 1] - samples[current]);
    const guess = intervalStart + dist * kSampleStepSize;
    const initialSlope = getSlope(guess, mX1, mX2);
    if (initialSlope >= 0.001) {
      let t = guess;
      for (let i = 0; i < 4; ++i) {
        const slope = getSlope(t, mX1, mX2);
        if (slope === 0.0) return t;
        t -= (calcBezier(t, mX1, mX2) - aX) / slope;
      }
      return t;
    }
    if (initialSlope === 0.0) return guess;
    let aA = intervalStart;
    let aB = intervalStart + kSampleStepSize;
    let t = 0;
    let x = 0;
    let i = 0;
    do {
      t = aA + (aB - aA) / 2.0;
      x = calcBezier(t, mX1, mX2) - aX;
      if (x > 0.0) aB = t;
      else aA = t;
    } while (Math.abs(x) > 0.0000001 && ++i < 10);
    return t;
  };
  return (x: number) => {
    const clamped = Math.min(1, Math.max(0, x));
    if (clamped === 0) return 0;
    if (clamped === 1) return 1;
    return calcBezier(tForX(clamped), mY1, mY2);
  };
}

/** How the count eases from `from` to `value`. */
export const easeCount = cubicBezier(0.3, 0, 0.12, 1);

/** Digits before the point once `v` is rounded to `decimals`. */
function intDigits(v: number, decimals: number) {
  const shown = Math.round(Math.abs(v) * 10 ** decimals) / 10 ** decimals;
  return Math.max(1, Math.floor(shown).toString().length);
}

// `enter` starts before the scene, so frame 0 is already part-way in.
// `count` runs from `from` to `value`; the digit widths relax to their
// natural set over its last `relax` frames. `drop:<j>` is the moment the
// figure loses its `j`th digit and the slot springs closed (the spring
// keeps its own pace; the length is about how long it takes). The drops
// follow the count. The label keeps its own time.
export const weightCutTimeline = defineTimeline<
  WeightCutElementId,
  WeightCutTimingProps
>(
  ({
    value = 6.8,
    from = 94,
    decimals = 1,
    count = COUNT_END - COUNT_AT,
  }): TimelineElement<WeightCutElementId>[] => {
    const countEnd = COUNT_AT + count;
    const drops: { at: number }[] = [];
    let prev = intDigits(from, decimals);
    for (let f = COUNT_AT; f <= countEnd; f += 0.25) {
      const g = easeCount((f - COUNT_AT) / (countEnd - COUNT_AT));
      const d = intDigits(from + (value - from) * g, decimals);
      if (d < prev) {
        for (let k = prev; k > d; k--) drops.push({ at: f });
        prev = d;
      }
    }
    const elements: TimelineElement<WeightCutElementId>[] = [
      {
        id: "enter",
        lane: "Figure",
        label: "enter",
        start: ENTER_AT,
        length: ENTER_END - ENTER_AT,
      },
      { id: "eyebrow", lane: "Copy", label: "eyebrow", start: 2, length: 16 },
      {
        id: "count",
        lane: "Figure",
        label: "count",
        start: COUNT_AT,
        length: count,
        beats: { relax: 10 },
      },
      ...drops.map(
        (d, j): TimelineElement<WeightCutElementId> => ({
          id: `drop:${j}`,
          lane: "Digits",
          label: `digit ${j + 1}`,
          start: d.at,
          length: 20,
          follows: "count",
        }),
      ),
      {
        id: "label",
        lane: "Copy",
        label: "label",
        start: LABEL_AT,
        length: 18,
      },
    ];
    return elements.sort((a, b) => a.start - b.start);
  },
);
